EXTRA_JS = r'''
const proofCases={late:['Submitted late','Late → Requires approval','Requires special approval',false],notapproval:['Does not require approval','No approval required → Not late','Not submitted late',false],approval:['Requires approval','Late → Requires approval','Lateness remains unknown',true],notlate:['Not submitted late','Late → Requires approval','Approval requirement unknown',true]};
function proofUpdate(){const c=proofCases[document.querySelector('#fact-choice').value];document.querySelector('#proof-given').textContent=c[0];document.querySelector('#proof-rule').textContent=c[1];document.querySelector('#proof-result').textContent=c[2];document.querySelector('#proof-flow').classList.toggle('flow-unknown',c[3]);document.querySelector('.result-node>span').textContent=c[3]?'What stays open':'Guaranteed result';}
document.querySelector('#fact-choice').addEventListener('change',proofUpdate);proofUpdate();
const motionButton=document.querySelector('#motion-toggle');let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;function setMotion(){document.body.classList.toggle('motion-paused',paused);motionButton.textContent=paused?'Play motion':'Pause motion';motionButton.setAttribute('aria-pressed',String(paused))}motionButton.addEventListener('click',()=>{paused=!paused;setMotion()});setMotion();
document.querySelector('#replay-flow').addEventListener('click',()=>{const flow=document.querySelector('#proof-flow');flow.getAnimations({subtree:true}).forEach(a=>{a.currentTime=0});proofUpdate();});
document.querySelectorAll('.pop-quiz').forEach(quiz=>{quiz.querySelectorAll('[data-answer]').forEach(button=>button.addEventListener('click',()=>{const correct=button.dataset.answer===quiz.dataset.correct;quiz.querySelectorAll('[data-answer]').forEach(b=>{b.classList.remove('is-correct','is-incorrect');b.setAttribute('aria-pressed','false')});button.setAttribute('aria-pressed','true');button.classList.add(correct?'is-correct':'is-incorrect');const feedback=quiz.querySelector('.quiz-feedback');feedback.hidden=false;quiz.querySelector('.quiz-verdict').textContent=correct?'Correct. The direction matters.':'Test the other possible case.';feedback.classList.remove('reveal');void feedback.offsetWidth;feedback.classList.add('reveal');feedback.focus();}));});
'''


def main():
    text, origin = source_text()
    renderer = Renderer()
    title, body = renderer.render(text)
    if renderer.checks != 6 or len(renderer.practice) != 4:
        raise ValueError('V4 must retain six typed checks and four mixed problems')
    data = json.dumps(renderer.practice, ensure_ascii=False).replace('<', '\\u003c')
    definitions_css = '.definitions{margin:0 0 28px;font-size:14px;line-height:1.55}.definitions>div{display:grid;grid-template-columns:90px 1fr;gap:12px;padding:7px 0}.definitions dt{font-weight:700;color:var(--violet)}.definitions>div:nth-child(2) dt{color:var(--blue)}.definitions>div:nth-child(3) dt{color:var(--teal)}.definitions dd{margin:0}.opening-story p:nth-of-type(2){border-color:var(--blue);background:linear-gradient(90deg,#edf2ff,transparent)}.opening-story p:nth-of-type(3){border-color:var(--violet);background:linear-gradient(90deg,#f2ecfa,transparent)}.opening-story p:nth-of-type(4){border-color:var(--teal);background:linear-gradient(90deg,#e6f4ed,transparent)}.opening-story p:nth-of-type(2) strong{color:var(--blue)}.opening-story p:nth-of-type(3) strong{color:var(--violet)}.opening-story p:nth-of-type(4) strong{color:var(--teal)}'
    page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="lsatu-interactive-lesson" content="yahunatan-2026-09-16-conditional-reasoning"><title>{html.escape(title)} | LSAT U</title><style>{CSS}{definitions_css}</style></head><body><header class="top"><b>LSAT U</b><div class="top-right"><span>Notes and recaps</span><button type="button" id="motion-toggle" aria-pressed="false">Pause motion</button></div></header><main class="lesson-shell"><h1 class="lesson-title">{html.escape(title)}</h1>{body}<footer>Start with what is given. Keep the whole idea. Follow the direction the rule supports.</footer></main><script>const practice={data};{base.JS}{EXTRA_JS}</script></body></html>'''
    if len(page.encode('utf-8')) >= 500_000 or 'concept lesson' in page.lower() or '\u2014' in page:
        raise ValueError('Student package violates size, wording, or punctuation requirements')
    OUTPUT.write_text(page, encoding='utf-8')
    print(f'{OUTPUT}\nSource: {origin}\nTyped checks: {renderer.checks}; pop quizzes: 2; mixed practice: {len(renderer.practice)}; bytes: {len(page.encode("utf-8"))}')


if __name__ == '__main__':
    main()
